    private Brand brand(String slug, String name, String description, String country) {
        Brand brand = brands.findBySlug(slug).orElseGet(Brand::new);
        brand.setSlug(slug); brand.setName(name); brand.setDescription(description);
        brand.setCountryOfOrigin(country); brand.setDemoData(true);
        return brand;
    }

    private void seedCategories() {
        categories.saveAll(List.of(
                category(ProductCategory.CLEANSER, "Cleansers", "cleansers"),
                category(ProductCategory.TONER, "Toners", "toners"),
                category(ProductCategory.SERUM, "Serums", "serums"),
                category(ProductCategory.MOISTURIZER, "Moisturizers", "moisturizers"),
                category(ProductCategory.SUNSCREEN, "Sunscreens", "sunscreens"),
                category(ProductCategory.TREATMENT, "Treatments", "treatments"),
                category(ProductCategory.MASK, "Masks", "masks"),
                category(ProductCategory.EYE_CARE, "Eye Care", "eye-care"),
                category(ProductCategory.LIP_CARE, "Lip Care", "lip-care"),
                category(ProductCategory.BODY_CARE, "Body Care", "body-care")));
    }

    private Category category(ProductCategory key, String name, String slug) {
        Category category = categories.findBySlug(slug).orElseGet(Category::new);
        category.setKey(key); category.setName(name); category.setSlug(slug);
        category.setDescription("Browse " + name.toLowerCase(java.util.Locale.ROOT) + " in the skincare catalogue.");
        category.setDemoData(true);
        return category;
    }

