    private Ingredient ingredient(String slug, String name, String whatItIs, String whatItDoes,
                                  List<String> uses, List<SkinConcern> concerns,
                                  List<String> compatible, List<String> caution) {
        Ingredient ingredient = ingredients.findBySlug(slug).orElseGet(Ingredient::new);
        ingredient.setSlug(slug); ingredient.setName(name); ingredient.setWhatItIs(whatItIs); ingredient.setWhatItDoes(whatItDoes);
        ingredient.setCommonUses(uses); ingredient.setSuitableSkinTypes(List.of(SkinType.NORMAL, SkinType.COMBINATION));
        ingredient.setTargetedConcerns(concerns); ingredient.setUsageInfo("Follow the product label. Introduce new products gradually and patch test first.");
        ingredient.setIrritationConsiderations("Tolerance depends on concentration, formulation, and individual skin. Seek professional advice for persistent concerns.");
        ingredient.setCompatibleIngredientSlugs(compatible); ingredient.setCautionIngredientSlugs(caution); ingredient.setDemoData(true);
        return ingredient;
    }

