    private void seedBrandFeaturedImages() {
        for (Brand brand : brands.findAll()) {
            products.findByBrandIdAndActiveTrue(brand.getId()).stream()
                    .filter(product -> product.getImages() != null && !product.getImages().isEmpty())
                    .filter(product -> product.getImages().get(0).startsWith("https://")
                            && !product.getImages().get(0).contains("product-placeholder.svg"))
                    .sorted(java.util.Comparator.comparing(Product::getSlug))
                    .findFirst()
                    .ifPresent(product -> brand.setFeaturedImageUrl(product.getImages().get(0)));
        }
        brands.saveAll(brands.findAll());
    }

    private void seedArticles() {
        if (articles.count() > 0) return;
        articles.saveAll(List.of(
                article("building-a-simple-routine", "Building a Simple Skincare Routine", "SKINCARE_BASICS",
                        "A practical introduction to the basic order of a skincare routine.",
                        "Start with a cleanser that feels comfortable, add one targeted product if it suits your needs, then moisturize. In the morning, finish with a broad-spectrum sunscreen according to its label. A simple routine is easier to evaluate than changing many products at once."),
                article("understanding-ingredient-lists", "How to Read an Ingredient List", "INGREDIENTS",
                        "Learn what ingredient lists can and cannot tell you.",
                        "Ingredient lists help you identify what a formula contains, but the list alone does not explain a product's strength or how your skin will respond. Read the directions, consider the full formula, and introduce products gradually. This educational sample is not medical advice."),
                article("patch-testing-new-products", "A Careful Approach to New Products", "SKINCARE_TIPS",
                        "A gentle process for introducing a new product into a routine.",
                        "Introduce one new product at a time and follow the package directions. A small-area patch test may help you notice irritation before wider use, but it cannot predict every reaction. Stop using a product if irritation occurs and seek professional advice when needed.")));
    }

    private Article article(String slug, String title, String category, String excerpt, String content) {
        return Article.builder().slug(slug).title(title).category(ArticleCategory.valueOf(category)).excerpt(excerpt)
                .content(content).author("GlowGuide Editorial").seoTitle(title + " | GlowGuide")
                .seoDescription(excerpt).demoData(true).build();
    }
